            a = tri[i][j]
            b = tri[i][j + 1]
            if a is not None and b is not None:
                numerator += float(b)
                denominator += float(a)
        if denominator > 0.0:
            factors.append(numerator / denominator)
        else:
            factors.append(1.0)

    ultimates = []
    for i in range(n):
        latest = None
        latest_index = -1
        for j in range(m):
            if tri[i][j] is not None:
                latest = float(tri[i][j])
                latest_index = j
        if latest is None:
            ultimates.append(0.0)
            continue
        value = latest
        for j in range(latest_index, m - 1):
            value *= factors[j]
        ultimates.append(value)

    return ultimates

